    wbLeadMin: 6,         // Weltboss: hinreisen, wenn er in so vielen min spawnt (bisher fest 6)
    eventsIdleMap: '',    // Warteplatz beim Warten auf Event/Weltboss ('' = stehen bleiben; z. B. 'network' – dort kein Tamer-DS-Verlust) (3.0.9)
