              const ents1 = window.dmo?.net?.state?.entities, meE = ents1?.get?.(ev.dst), aId = cl ? (cl.slot === group.slot() ? me0.partner?.entityId : group.peers.get(cl.slot)?.ents?.[1]) : null, aE = aId && ents1?.get?.(aId);
