    if (ro.role === 'grpheal') { const low = partyPartners(st, reach).filter((m) => m.maxHp > 0 && pct(m.hp, m.maxHp) < ro.n); return low.length ? `${low.map((m) => m.name).join(', ')} unter ${ro.n} %` : null; }
