  const CARD_ELITE_DETOUR = 400; // Elites (doppelte Karte, kaum mehr HP) auch so weit außerhalb des Radius vorziehen (3.1.41)
  const CARD_NAMED_DROP = 12;   // Named-Gegner: feste 12 Common-Karten je Kill
