      if (!t || (t.rarity !== 0 && t.rarity !== 1) || !/^card_/.test(it.id || '')) continue;
      const limit = (t.baseUses || 0) + (t.masteryPoints || 0) * (t.masteryCopiesPerPoint || 34);
