    const handOff = (m) => !!palNear && bladeBreaks.has(m.species) && m.maxHp > 0 && m.hp / m.maxHp < DG_BLADE_HANDOFF
      && sc.mobs.filter((x) => x.species === m.species && x.hp > 0).length === 1 && Math.hypot(palNear.x - m.x, palNear.y - m.y) <= DG_BLADE_HANDOFF_R;
