      if (R.blocked || notOk.length) why = `warte auf die Party – ${notOk.map((m) => `${m.name || '?'} ${RAID_CHECK_TXT[m.check] || m.check}`).join(', ') || RAID_BLOCK_TXT[R.blocked] || R.blocked}`;
