    const c = open[0], p = mid(c);
    const s = go(p.x, p.y, `erkunde ${c.role?.startsWith('deadend') ? 'Sackgasse' : c.role === 'branch' ? 'Abzweig' : c.role === 'main' ? 'Hauptweg' : c.role || 'Zelle'} ${rift.visited.size + 1}/${cells.length}`);
