    const ct = circleTail, tail = ct.n ? ` · Kreis-Nachlauf ${ct.n}× Σ ${(ct.sum / 1000).toFixed(1)} s (max ${Math.round(ct.max)} ms, Einschlag spätestens ${Math.round(ct.relLate)} ms nach Ende)` : '';
