    if (rift.biomeKey !== key) { Object.assign(rift, { biomeKey: key, giveUp: false, biomeOk: null, biomeFloor: 0, biomeLeft: false, enterTries: 0, talkTries: 0, breadTries: 0, breadAt: 0, scanFresh: false, warned: '' }); }
